svg.script:
fetch('/api/briefing')
  .then(function (response) {
    if (!response.ok) {
      throw new Error('HTTP ' + response.status);
    }
    return response.text();
  })
  .then(function (result) {
    alert(result);
  })
  .catch(function (error) {
    alert('요청 실패: ' + error.message);
  });
